      await fetch(`/api/academic/levels/${activeLevelForAction.id}/verify-director-email`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          email: activeLevelForAction.directorEmail || directorForm.directorEmail,
          code: otpCodeInput,
        }),
      });

      setEducationalLevels((prev) =>
        prev.map((lvl) => (lvl.id === activeLevelForAction.id ? { ...lvl, isEmailVerified: true } : lvl))
      );

      setShowVerifyDirectorModal(false);
      setIsVerifyingOtp(false);
      showToast(`🎉 ¡Director(a) verificado(a) exitosamente! Ya puede añadir a sus maestros.`);
