  const handleEnrollStudentWorkshop = async (e: React.FormEvent) => {
    e.preventDefault();
    const workshop = extracurricularWorkshops.find((w) => w.id === enrollWorkshopForm.workshopId);
    if (!workshop) return;

    if (workshop.enrolledCount >= workshop.maxCapacity) {
      showToast(`⚠️ El taller ${workshop.name} no tiene cupos disponibles.`);
      return;
    }

    const alreadyEnrolled = workshopEnrollments.some(
      (enr) =>
        enr.workshopId === enrollWorkshopForm.workshopId &&
        enr.studentId === enrollWorkshopForm.studentId &&
        enr.status === 'ACTIVO'
    );
    if (alreadyEnrolled) {
      showToast('⚠️ El alumno ya está inscrito en esta academia.');
      return;
    }

    const student = students.find((s) => s.id === enrollWorkshopForm.studentId);
    const newEnrollment: WorkshopEnrollmentItem = {
      id: `wenr-${Date.now()}`,
      workshopId: workshop.id,
      workshopName: workshop.name,
      workshopCode: workshop.code,
      studentId: enrollWorkshopForm.studentId,
      studentName: student ? `${student.firstName} ${student.lastName}` : 'Alumno',
      studentCode: student?.studentCode || '2026-PRI-000',
      groupName: 'Primaria 1º "A"',
      enrollmentDate: new Date().toISOString().split('T')[0],
      monthlyFeeMXN: workshop.monthlyFeeMXN,
      parentAuthorization: true,
      status: 'ACTIVO',
    };

    setWorkshopEnrollments((prev) => [...prev, newEnrollment]);
    setExtracurricularWorkshops((prev) =>
      prev.map((w) =>
        w.id === workshop.id
          ? {
              ...w,
              enrolledCount: w.enrolledCount + 1,
              status: w.enrolledCount + 1 >= w.maxCapacity ? 'CERRADO_CUPO_LLENO' : w.status,
            }
          : w
      )
    );

    if (isOnline) {
      try {
        await fetch('/api/academic/workshops/enrollments', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(enrollWorkshopForm),
        });
      } catch (err) {
        // offline fallback
      }
    }

    setShowEnrollWorkshopModal(false);
    showToast(`✅ Alumno inscrito a "${workshop.name}". Cupo actualizado.`);
  };

