  const handleResolveMaintenanceTicket = async (ticketId: string) => {
    const ticket = assetMaintenanceTickets.find((t) => t.id === ticketId);
    if (!ticket) return;

    const now = new Date();
    const resolvedAt = `${now.toISOString().split('T')[0]} ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;

    setAssetMaintenanceTickets((prev) =>
      prev.map((t) =>
        t.id === ticketId
          ? {
              ...t,
              status: 'RESUELTO',
              resolvedAt,
              resolutionNotes: 'Trabajo de reparación e inspección completado satisfactoriamente.',
            }
          : t
      )
    );

    // Restaurar condición del activo
    setSchoolAssets((prev) =>
      prev.map((a) => (a.id === ticket.assetId ? { ...a, condition: 'BUENO' } : a))
    );

    if (isOnline) {
      try {
        await fetch(`/api/academic/inventory/tickets/${ticketId}/status`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            status: 'RESUELTO',
            resolutionNotes: 'Trabajo de reparación e inspección completado satisfactoriamente.',
          }),
        });
      } catch (err) {
        // offline fallback
      }
    }

    showToast(`✅ Ticket ${ticket.ticketNumber} marcado como resuelto.`);
  };

