  // --- HANDLERS: CERTIFICACIÓN DIGITAL & KÁRDEX OFICIAL ---
  const handleCreateOfficialCertificate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCertificateForm.studentName.trim()) {
      showToast('⚠️ Ingresa el nombre del alumno.');
      return;
    }

    const typePrefix =
      newCertificateForm.type === 'CONSTANCIA_ESTUDIOS_SIMPLE'
        ? 'CE'
        : newCertificateForm.type === 'CONSTANCIA_INSCRIPCION'
        ? 'CI'
        : newCertificateForm.type === 'CONSTANCIA_BUENA_CONDUCTA'
        ? 'CC'
        : newCertificateForm.type === 'CONSTANCIA_PROMEDIO'
        ? 'CP'
        : 'KD';

    const year = new Date().getFullYear();
    const folio = `${typePrefix}-${year}-${String(officialCertificates.length + 1).padStart(3, '0')}`;
    const token = `tok-${Date.now().toString(36)}-${Math.random().toString(36).substring(2, 8)}`;

    const sealData = `${folio}|${newCertificateForm.studentCode}|${newCertificateForm.curp}|${newCertificateForm.grade}`;
    let hash = 0;
    for (let i = 0; i < sealData.length; i++) {
      hash = (hash << 5) - hash + sealData.charCodeAt(i);
      hash |= 0;
    }
    const digitalSeal = Array.from({ length: 4 }, (_, idx) =>
      Math.abs((hash ^ (idx * 0x5bd1e995)) >>> 0).toString(16).padStart(8, '0')
    ).join('') + '9f0a1b2c3d4e5f6a7b8c9d0e1f2a3b4c';

    const issueDate = new Date().toISOString().split('T')[0];
    const expiry = new Date();
    expiry.setDate(expiry.getDate() + 90);
    const validUntil = expiry.toISOString().split('T')[0];

    const newCert: OfficialCertificateItem = {
      id: `cert-${Date.now()}`,
      folio,
      verificationToken: token,
      studentId: newCertificateForm.studentId,
      studentName: newCertificateForm.studentName,
      studentCode: newCertificateForm.studentCode,
      curp: newCertificateForm.curp,
      level: newCertificateForm.level,
      grade: newCertificateForm.grade,
      groupName: newCertificateForm.groupName,
      academicCycle: newCertificateForm.academicCycle,
      type: newCertificateForm.type,
      issueDate,
      validUntil,
      status: 'EMITIDA',
      averageGrade: Number(newCertificateForm.averageGrade) || 9.0,
      issuedByDirector: newCertificateForm.issuedByDirector,
      directorCedula: newCertificateForm.directorCedula,
      digitalSeal,
      notes: newCertificateForm.notes,
      downloadCount: 0,
      qrValidationUrl: `/verify/doc/${token}`,
      createdAt: new Date().toISOString(),
    };

    setOfficialCertificates((prev) => [newCert, ...prev]);

    if (isOnline) {
      try {
        await fetch('/api/academic/certificates', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            studentId: newCert.studentId,
            studentName: newCert.studentName,
            studentCode: newCert.studentCode,
            curp: newCert.curp,
            level: newCert.level,
            grade: newCert.grade,
            groupName: newCert.groupName,
            academicCycle: newCert.academicCycle,
            type: newCert.type,
            averageGrade: newCert.averageGrade,
            notes: newCert.notes,
            issuedByDirector: newCert.issuedByDirector,
            directorCedula: newCert.directorCedula,
          }),
        });
      } catch (err) {
        // offline fallback
      }
    }

    setShowNewCertificateModal(false);
    showToast(`📜 ${newCert.type.replace(/_/g, ' ')} emitida con folio ${newCert.folio}.`);
  };

  const handleRevokeCertificate = async (certId: string) => {
    const reason = window.prompt('Ingresa el motivo de revocación del documento oficial:');
    if (!reason) return;

    setOfficialCertificates((prev) =>
      prev.map((c) =>
        c.id === certId
          ? {
              ...c,
              status: 'REVOCADA',
              notes: `${c.notes ? c.notes + ' • ' : ''}REVOCADO: ${reason}`,
            }
          : c
      )
    );

    if (isOnline) {
      try {
        await fetch(`/api/academic/certificates/${certId}/revoke`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ reason }),
        });
      } catch (err) {
        // offline fallback
      }
    }

    showToast('⚠️ El documento ha sido revocado oficialmente.');
  };

  const handleVerifyDocumentToken = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!verifierQueryToken.trim()) return;

    const token = verifierQueryToken.trim();
    const cert = officialCertificates.find((c) => c.verificationToken === token || c.folio === token);
    const now = new Date().toISOString().split('T')[0];

    if (!cert) {
      setVerifierResult({
        checked: true,
        isValid: false,
        message: 'No existe ningún documento oficial registrado con este token criptográfico o folio.',
      });
      return;
    }

    if (cert.status === 'REVOCADA') {
      setVerifierResult({
        checked: true,
        isValid: false,
        certificate: cert,
        message: 'DOCUMENTO REVOCADO: La institución canceló la validez jurídica de esta constancia.',
      });
      return;
    }

    if (cert.validUntil < now) {
      setVerifierResult({
        checked: true,
        isValid: false,
        certificate: cert,
        message: 'DOCUMENTO EXPIRADO: La vigencia reglamentaria de 90 días naturales ha concluido.',
      });
      return;
    }

    setVerifierResult({
      checked: true,
      isValid: true,
      certificate: cert,
      message: 'DOCUMENTO AUTÉNTICO: Sello digital y matrícula válidos en el Registro Escolar.',
    });
  };

