  const handleToggleCommissionStatus = async (
    eventId: string,
    commissionId: string,
    newStatus: TeacherEventCommissionItem['status']
  ) => {
    setSchoolEvents((prev) =>
      prev.map((evt) => {
        if (evt.id !== eventId) return evt;
        return {
          ...evt,
          commissions: evt.commissions.map((c) =>
            c.id === commissionId ? { ...c, status: newStatus } : c
          ),
        };
      })
    );

    if (selectedEventForDetail && selectedEventForDetail.id === eventId) {
      setSelectedEventForDetail((prev) =>
        prev
          ? {
              ...prev,
              commissions: prev.commissions.map((c) =>
                c.id === commissionId ? { ...c, status: newStatus } : c
              ),
            }
          : null
      );
    }

    if (isOnline) {
      try {
        await fetch(`/api/academic/events/${eventId}/commissions/${commissionId}/status`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ status: newStatus }),
        });
      } catch (err) {
        // offline fallback
      }
    }

    showToast(`✅ Estatus de comisión actualizado a ${newStatus}.`);
  };

